const clone=x=>JSON.parse(JSON.stringify(x));
const stable=x=>Array.isArray(x)?'['+x.map(stable).join(',')+']':x&&typeof x==='object'?'{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+stable(x[k])).join(',')+'}':JSON.stringify(x);
function validateTable(table,allowLegacy=false){
 if(!table||Object.keys(table).length!==240)throw Error('Нужны все 120 встреч для обоих кубиков');
 for(const s of ['sc1_rats','sc2_king','sc3_wolves','sc4_alpha','sc5_bandits'])for(const d of ['easy','normal','hard'])for(let n=1;n<=8;n++){
  const a=table[s+'/'+d+'/d20/'+n],b=table[s+'/'+d+'/d10/'+n];
  if(!Array.isArray(a)||!a.length||!Array.isArray(b)||!b.length)throw Error('Отсутствует встреча '+s+'/'+d+'/'+n);
  if(!allowLegacy&&stable(a)!==stable(b))throw Error('Враги D20 и 2D10 различаются: '+s+'/'+d+'/'+n+'. Нужна единая таблица.');
  for(const rows of [a,b]){const seen=new Set();let count=0;for(const r of rows){
   if(!r||typeof r.key!=='string'||seen.has(r.key))throw Error('Повторный или неизвестный вид врага');seen.add(r.key);
   if(!Number.isInteger(r.count)||r.count<0||!Number.isInteger(r.hp)||r.hp<1||r.hp>5000||!Number.isInteger(r.atk)||r.atk<0||r.atk>100)throw Error('Некорректные числа встречи');
   if(r.potions!=null&&(!Number.isInteger(r.potions)||r.potions<0||r.potions>20))throw Error('Некорректное число зелий');count+=r.count;
  }if(count<1||count>g.Workshop.cap(n))throw Error('Нарушен лимит врагов');}
 }
 return true;
}
function migrateD20(table){validateTable(table,true);const out={};for(const [key,rows] of Object.entries(table))if(key.includes('/d20/')){out[key]=clone(rows);out[key.replace('/d20/','/d10/')]=clone(rows);}validateTable(out);return out;}
function attach(){for(const chapter of Object.values(g.chaptersDB||{}))for(const s of chapter.scenarios||[])if(s.configs)for(const d of Object.keys(s.configs))if(TABLE[s.id+'/'+d+'/d20/1'])s.configs[d].sessionBalance35={sceneId:s.id,difficulty:d};}attach();
function rowsFor(scene,difficulty,mode,players){if(!Number.isInteger(players)||players<1||players>8)throw Error('Допустимо от 1 до 8 игроков');const row=TABLE[scene+'/'+difficulty+'/d20/'+players];return row?clone(row):null;}
function plan(cfg,players,mode){const tag=(cfg||{}).sessionBalance35;if(!tag)return null;const rows=rowsFor(tag.sceneId,tag.difficulty,mode,players);if(!rows)return null;const list=[];rows.forEach(r=>{for(let i=0;i<r.count;i++)list.push(r.key)});return {list,rows,buffRatio:1,elite:false,multiplier:1,balancedProfile:true,profileId:'fix33-shared-v2',playerCount:players,mode:mode==='d20'?'d20':'d10'};}
function enemy(cfg,p,key){const row=p.rows.find(r=>r.key===key);if(!row)throw Error('Нет вида в выбранной встрече: '+key);const src=(g.enemiesDB||{})[key]||(g.customCreaturesDB||{})[key]||{};return {...src,...row,ai:{...(src.ai||{}),...(row.ai||{}),params:{...(src.ai?.params||{}),...(row.ai?.params||{})}},maxHP:row.hp,hp:row.hp,currentHP:row.hp,potionHeal:row.heal??src.potionHeal??0};}
function potionTotals(cfg,p){return Object.fromEntries(p.rows.filter(r=>r.count>0&&r.potions>0).map(r=>[r.key,r.potions]));}
function potions(cfg,p,rng){const out=g.CombatRules.distributeEnemyPotions(p.list,potionTotals(cfg,p));const ids=p.list.map((k,i)=>k==='bandit'?i:-1).filter(i=>i>=0);if(ids.length&&ids.reduce((a,i)=>a+out[i],0)===1){ids.forEach(i=>out[i]=0);out[ids[Math.min(ids.length-1,Math.floor(rng()*ids.length))]]=1;}return out;}
g.GrivensburgSessionBalance={data:{id:'fix33-shared-v2-2026-10-30',balancePolicy:'shared-dice',maxPlayers:8,table:TABLE},attach,rowsFor,plan,enemy,potionTotals,potions,validateTable,migrateD20,stable};
